style.css:
@-moz-document domain("pinterest.com") {
/* ═══════════════════════════════
        ✦ ANGEL1C PINTEREST ✦
   Blanco • Gris • Angelcore
═══════════════════════════════ */

:root{
    --bg:#fafafa;
    --panel:rgba(255,255,255,.82);
    --border:#ececec;
    --text:#222;
    --shadow:rgba(0,0,0,.08);
}

/* Fondo */

body{
    background:var(--bg)!important;
}

/* Estrellitas */

body::before{
    content:"";
    position:fixed;
    inset:0;
    pointer-events:none;
    background-image:
        radial-gradient(circle,#dadada 1px,transparent 1px),
        radial-gradient(circle,#efefef 1px,transparent 1px);
    background-size:90px 90px,160px 160px;
    opacity:.35;
    z-index:999999;
}

/* Alas */

body::after{
    content:"?";
    position:fixed;
    top:20px;
    left:20px;
    font-size:38px;
    opacity:.25;
    pointer-events:none;
    z-index:999999;
}

html::before{
    content:"?";
    position:fixed;
    top:20px;
    right:20px;
    font-size:38px;
    opacity:.25;
    pointer-events:none;
    z-index:999999;
}

html::after{
    content:"?";
    position:fixed;
    bottom:20px;
    right:20px;
    font-size:38px;
    opacity:.25;
    pointer-events:none;
    z-index:999999;
}

/* Tarjetas */

[data-test-id="pin"]{
    border-radius:22px!important;
    overflow:hidden;
    transition:.25s;
}

[data-test-id="pin"]:hover{
    transform:translateY(-4px);
    box-shadow:
        0 10px 28px rgba(0,0,0,.12);
}

/* Buscador */

input{
    border-radius:999px!important;
}

/* Botones */

button{
    border-radius:999px!important;
    transition:.25s;
}

button:hover{
    transform:scale(1.03);
}

/* Scroll */

::-webkit-scrollbar{
    width:10px;
}

::-webkit-scrollbar-thumb{
    background:#d5d5d5;
    border-radius:999px;
}
}
